using KitWright.Editor.Tools.Scripting;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using System.Text;
using System.Linq;

public class CommandScript : IKitWrightCommand
{
    public void Execute(ExecutionContext ctx)
    {
        var scene = EditorSceneManager.GetActiveScene();
        var sb = new StringBuilder();
        sb.AppendLine("active=" + scene.path);
        sb.AppendLine("play=" + EditorApplication.isPlaying);

        void Dump(Transform t, int d)
        {
            if (d > 3) return;
            sb.AppendLine(new string(' ', d * 2) + t.name + " active=" + t.gameObject.activeSelf);
            for (int i = 0; i < t.childCount; i++) Dump(t.GetChild(i), d + 1);
        }

        foreach (var root in scene.GetRootGameObjects())
            Dump(root.transform, 0);

        ctx.ReturnValue = sb.ToString();
    }
}
